from app.config import OpenCodeZenSettings
from app.models import ModelEnum
import httpx

settings = OpenCodeZenSettings()

MODEL_KEY_MAP = {
    ModelEnum.claude_fable_5: settings.opencode_zen_claude_fable_5_key,
    ModelEnum.gemini_3_1_pro: settings.opencode_zen_gemini_3_1_pro_key,
}

def get_model_client(model: ModelEnum) -> httpx.AsyncClient:
    try:
        api_key = MODEL_KEY_MAP[model]
    except KeyError:
        raise ValueError(f"No OpenCode Zen key configured for model: {model}")
    
    return httpx.AsyncClient(
        headers={"Authorization": f"Bearer {api_key}"},
        base_url="https://api.opencodezen.com/v1"
    )


# File: app/services/llm_service.py
from app.client_factory import get_model_client
from app.models import ModelEnum
import httpx

async def generate_completion(model: ModelEnum, prompt: str) -> str:
    client = get_model_client(model)
    try:
        response = await client.post("/completions", json={"prompt": prompt})
        response.raise_for_status()
        return response.json()["completion"]
    finally:
        await client.aclose()


