import pytest
from app.services.llm_service import generate_completion
from app.models import ModelEnum
from unittest.mock import AsyncMock, patch

@pytest.mark.asyncio
async def test_generate_completion_calls_correct_endpoint():
    mock_client = AsyncMock()
    mock_client.post.return_value = AsyncMock(
        status_code=200,
        json=lambda: {"completion": "test-response"}
    )
    
    with patch("app.client_factory.get_model_client", return_value=mock_client):
        result = await generate_completion(ModelEnum.claude_fable_5, "test-prompt")
        assert result == "test-response"
        mock_client.post.assert_called_once_with("/completions", json={"prompt": "test-prompt"})


